-- random data for e2e tests
-- Applied by global-setup.ts, removed by global-teardown.ts.

ON CONFLICT (park_id, cell_ref) DO NOTHING;

WITH model AS (
        park_id, version, object_storage_key, is_active, trained_by,
        training_window_start, training_window_end, n_training_examples, metrics
    )
    SELECT
        'klaserie', 1, 'e2e-fixture/risk-v1', TRUE, u.id,
        TIMESTAMPTZ '2026-07-15T00:00:00Z', TIMESTAMPTZ '2026-08-15T00:00:00Z', 500,
        '{"auc": 0.82, "precision": 0.71, "recall": 0.68}'::jsonb
    FROM users u
    WHERE u.username = 'analyst1'
    RETURNING id
),
heatmaps AS (
    SELECT model.id, '1km', '6h', t.computed_at
    FROM model, (VALUES
        (TIMESTAMPTZ '2026-08-15T00:00:00Z'),
        (TIMESTAMPTZ '2026-08-15T06:00:00Z'),
        (TIMESTAMPTZ '2026-08-15T12:00:00Z'),
        (TIMESTAMPTZ '2026-08-15T18:00:00Z')
    ) AS t(computed_at)
    RETURNING id
)
SELECT h.id, gc.id, ROUND((0.10 + 0.35 * random())::numeric, 3)
FROM heatmaps h
CROSS JOIN grid_cells gc
WHERE gc.park_id = 'klaserie';
